690	import {
691	  GraphPointer,
692	} from "./graph-pointer.js";
693	import {
694	  RuleRef,
695	} from "./rule-ref.js";
696	import {
697	  Range,
698	  RuleType,
699	  type RuleChar,
700	  type RuleCharExclude,
701	  type RuleEnd,
702	  type UnresolvedRule,
703	} from "./types.js";
704	
705	/** Type Guards */
706	export const isRuleType = (type?: unknown): type is RuleType => !!type && Object.values(RuleType).includes(type as RuleType);
707	export const isRule = (rule?: unknown): rule is UnresolvedRule => !!rule && typeof rule === 'object' && 'type' in rule && isRuleType(rule.type);
708	export const isRuleRef = (rule?: UnresolvedRule): rule is RuleRef => rule instanceof RuleRef;
709	export const isRuleEnd = (rule?: UnresolvedRule): rule is RuleEnd => rule !== undefined && !(isRuleRef(rule)) && rule.type === RuleType.END;
710	export const isRuleChar = (rule?: UnresolvedRule): rule is RuleChar => rule !== undefined && !(isRuleRef(rule)) && rule.type === RuleType.CHAR;
711	export const isRuleCharExcluded = (rule?: UnresolvedRule): rule is RuleCharExclude => rule !== undefined && !(isRuleRef(rule)) && rule.type === RuleType.CHAR_EXCLUDE;
712	export const isRange = (range?: unknown): range is Range => Array.isArray(range) && range.length === 2 && range.every(n => typeof n === 'number');
713	
