            [[{"type": "CHAR", "value": [97]}, {"type": "END"}]], self.defs('root ::= "a"')
        )

    def test_alternates_insert_an_alt_marker(self) -> None:
        self.assertEqual(
            [
                [
                    {"type": "CHAR", "value": [97]},
                    {"type": "ALT"},
                    {"type": "CHAR", "value": [98]},
                    {"type": "END"},
